import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const f=JSON.parse('{"title":"Signed Catalog & Anti-Spoofing","description":"","frontmatter":{},"headers":[],"relativePath":"security/signed-catalog.md","filePath":"security/signed-catalog.md","lastUpdated":1795176120000}'),d={name:"security/signed-catalog.md"};function c(n,e,r,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="signed-catalog-anti-spoofing" tabindex="-1">Signed Catalog &amp; Anti-Spoofing <a class="header-anchor" href="#signed-catalog-anti-spoofing" aria-label="Permalink to &quot;Signed Catalog &amp; Anti-Spoofing&quot;">​</a></h1><p>JetPack enforces a hard security boundary between <strong>Verified App Store Catalog</strong> applications and <strong>Local Unverified Developer</strong> applications (<code>crates/jetpack-daemon/src/catalog.rs</code>).</p><h2 id="_1-embedded-platform-root-key-catalog-verify-pubkey" tabindex="-1">1. Embedded Platform Root Key (<code>CATALOG_VERIFY_PUBKEY</code>) <a class="header-anchor" href="#_1-embedded-platform-root-key-catalog-verify-pubkey" aria-label="Permalink to &quot;1. Embedded Platform Root Key (`CATALOG_VERIFY_PUBKEY`)&quot;">​</a></h2><p><code>jetpack-daemon</code> compiles in the platform&#39;s 32-byte <code>Ed25519</code> verifying public key (<code>CATALOG_VERIFY_PUBKEY</code>) alongside the embedded base <code>SignedAppCatalog</code> (<code>crates/jetpack-daemon/assets/catalog.signed.json</code>).</p><ul><li>Outside <code>#[cfg(test)]</code>, <code>CATALOG_VERIFY_PUBKEY</code> is strictly immutable and cannot be overridden by <code>daemon.toml</code>, environment variables, or WebSocket control-plane opcodes.</li><li>Before trusting any catalog entry (remote, cached, or embedded), <code>SignedAppCatalog::from_signed_json_and_verify</code> computes the canonical payload bytes (<code>SignedAppCatalog::canonical_payload_bytes()</code>, covering <code>version</code>, ordered <code>apps</code> entries, and <code>coming_soon</code>) and verifies <code>ed25519_signature</code> using <code>ed25519-dalek</code>.</li><li>Any tampering with <code>oci_reference</code>, <code>manifest_sha256</code>, <code>allowed_origins</code>, <code>coming_soon</code>, <code>version</code>, or <code>min_vram_mb</code>—or a signature produced by an untrusted keypair—fails immediately with <code>JetPackError::CatalogSignatureInvalid</code>.</li></ul><h2 id="_2-remote-catalog-refresh-verified-caching-offline-fallback" tabindex="-1">2. Remote Catalog Refresh, Verified Caching &amp; Offline Fallback <a class="header-anchor" href="#_2-remote-catalog-refresh-verified-caching-offline-fallback" aria-label="Permalink to &quot;2. Remote Catalog Refresh, Verified Caching &amp; Offline Fallback&quot;">​</a></h2><p><code>DaemonConfig</code> (<code>&lt;root&gt;/config/daemon.toml</code>) configures an optional top-level <code>catalog_url</code> defaulting to <code>https://raw.githubusercontent.com/jetpack-io/jetpack/main/crates/jetpack-daemon/assets/catalog.signed.json</code> (setting <code>catalog_url = &quot;&quot;</code> disables remote fetches cleanly for air-gapped setups). Non-empty URLs must use <code>https://</code> (or loopback <code>http://127.0.0.1</code> / <code>localhost</code> / <code>::1</code> for local testing).</p><p>When an authenticated client requests <code>&quot;catalog.get&quot;</code>:</p><ol><li><strong>Bounded HTTPS Fetch</strong>: The daemon asynchronously fetches <code>catalog.signed.json</code> with a strict <strong>3-second</strong> timeout and a 2 MiB response size cap via <code>reqwest</code> (<code>rustls-tls</code>).</li><li><strong>Signature &amp; Anti-Rollback Check</strong>: The remote payload must verify against <code>CATALOG_VERIFY_PUBKEY</code> and have <code>remote.version &gt;= embedded.version</code>.</li><li><strong>Atomic Cache Persistence</strong>: Validated catalogs are atomically written to <code>&lt;root&gt;/config/catalog.cached.json</code> (<code>0600</code> permissions on Unix).</li><li><strong>Transparent Fallback</strong>: If the network is unreachable, times out, returns an error, or presents a tampered/rolled-back payload, the existing cache is <strong>never</strong> overwritten and the daemon transparently falls back to the last verified <code>&lt;root&gt;/config/catalog.cached.json</code> (if valid and <code>cached.version &gt;= embedded.version</code>) or the compiled-in <code>EMBEDDED_SIGNED_CATALOG_JSON</code>.</li></ol><h2 id="_3-verified-network-pulls-coming-soon-digest-pinning" tabindex="-1">3. Verified Network Pulls, <code>coming_soon</code> &amp; Digest Pinning <a class="header-anchor" href="#_3-verified-network-pulls-coming-soon-digest-pinning" aria-label="Permalink to &quot;3. Verified Network Pulls, `coming_soon` &amp; Digest Pinning&quot;">​</a></h2><p>When an authenticated client invokes <code>&quot;app.pull&quot;</code>:</p><ol><li><strong>Catalog-Only Network Pulls</strong>: The daemon resolves <code>app_id</code> or <code>oci_reference</code> exclusively against the active verified <code>SignedAppCatalog</code>. Any request targeting an unlisted image returns <code>&quot;app.error&quot;</code> with code <code>UNVERIFIED_APP_BLOCKED</code> without contacting any remote registry.</li><li><strong><code>coming_soon</code> Availability Enforcement</strong>: Announced future catalog entries marked <code>coming_soon: true</code> (rendered in the Control Center Store with a non-interactive <strong>Coming Soon</strong> badge) are rejected on <code>&quot;app.pull&quot;</code> with <code>PROVISIONING_FAILED</code> before contacting any OCI registry.</li><li><strong>No Browser Privilege Escalation</strong>: Even if <code>&quot;settings.set&quot;</code> toggles <code>developer_mode = true</code>, browser WebSocket sessions are <strong>never</strong> permitted to pull unverified OCI references from the network.</li><li><strong>Immutable Digest &amp; Reference Pinning</strong>: Client-supplied registry URLs, tags, or digest overrides are ignored. The daemon pulls strictly from <code>CatalogAppEntry.oci_reference</code> and verifies that the resolved OCI manifest digest matches <code>CatalogAppEntry.manifest_sha256</code>.</li><li><strong>Inner Manifest App ID Verification</strong>: After unpacking the OCI layer (with Tar-Slip path traversal checks), the daemon verifies that <code>app.toml</code>&#39;s <code>[package].id</code> matches <code>CatalogAppEntry.app_id</code>. Mismatches are rejected with <code>APP_SPOOFING_DETECTED</code> or <code>PROVISIONING_FAILED</code> before materializing into <code>&lt;root&gt;/apps/</code>.</li></ol><h2 id="_4-anti-spoofing-for-local-developer-apps-vs-curated-offline-seeding" tabindex="-1">4. Anti-Spoofing for Local Developer Apps vs. Curated Offline Seeding <a class="header-anchor" href="#_4-anti-spoofing-for-local-developer-apps-vs-curated-offline-seeding" aria-label="Permalink to &quot;4. Anti-Spoofing for Local Developer Apps vs. Curated Offline Seeding&quot;">​</a></h2><p>Developers can install custom local workers on their own machine using the CLI (<code>jetpack-daemon --install-local-app &lt;dir&gt;</code>):</p><ul><li><strong>Official ID Protection</strong>: If a local app&#39;s <code>app.toml</code> attempts to use an <code>app_id</code> reserved in <code>SignedAppCatalog</code> (such as <code>io.jetpack.media-converter</code>), <code>--install-local-app</code> rejects it with <code>APP_SPOOFING_DETECTED</code>.</li><li><strong>Verified Provenance Tracking</strong>: Apps installed via verified catalog <code>&quot;app.pull&quot;</code>—or seeded strictly from the daemon&#39;s curated <code>examples/</code> allowlist (<code>--seed-core-apps</code> / first-run hook guarded by <code>&lt;root&gt;/config/.core-apps-seeded</code>)—carry verified provenance (<code>is_verified = true</code> in <code>AppInfo</code>). Custom local apps always report <code>is_verified = false</code> and display a yellow <code>UNVERIFIED / LOCAL DEV</code> badge in the Control Center and system tray.</li></ul><h2 id="_5-per-application-websocket-origin-authorization" tabindex="-1">5. Per-Application WebSocket <code>Origin</code> Authorization <a class="header-anchor" href="#_5-per-application-websocket-origin-authorization" aria-label="Permalink to &quot;5. Per-Application WebSocket `Origin` Authorization&quot;">​</a></h2><p>Having a paired WebSocket session does <strong>not</strong> grant a web origin access to every installed worker on the user&#39;s machine. Before <code>&quot;app.launch&quot;</code> or forwarding any <code>HybridFrame</code> with <code>target_worker</code> set, <code>jetpack-daemon</code> checks:</p><table tabindex="0"><thead><tr><th style="text-align:left;">App Provenance</th><th style="text-align:left;">Authorized WebSocket <code>Origin</code>s</th><th style="text-align:left;">Unauthorized Result</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Verified Catalog App</strong> (<code>is_verified = true</code>)</td><td style="text-align:left;">Normalized origins listed in <code>CatalogAppEntry.allowed_origins</code> <strong>OR</strong> the embedded Control Center origin (<code>http://127.0.0.1:&lt;port&gt;</code>)</td><td style="text-align:left;">Rejected with <code>&quot;app.error&quot;</code> code <code>ORIGIN_NOT_AUTHORIZED_FOR_APP</code></td></tr><tr><td style="text-align:left;"><strong>Local Developer App</strong> (<code>is_verified = false</code>)</td><td style="text-align:left;">Loopback HTTP origins only (<code>http://127.0.0.1[:port]</code>, <code>http://localhost[:port]</code>)</td><td style="text-align:left;">Rejected with <code>&quot;app.error&quot;</code> code <code>ORIGIN_NOT_AUTHORIZED_FOR_APP</code></td></tr></tbody></table><p>Remote paired origins (e.g. <code>https://app.example.com</code>) can never launch or send IPC frames to unverified local-dev workers, nor can one catalog app&#39;s origin invoke another catalog app&#39;s worker unless explicitly authorized in <code>allowed_origins</code>.</p>',19)])])}const h=o(d,[["render",c]]);export{f as __pageData,h as default};
